function recommendLanguage(domain) {
  if (domain === "web-frontend") return "JavaScript / TypeScript";
  if (domain === "data-science") return "Python";
  if (domain === "game-engine") return "C++";
  return "General Purpose";
}
let chosen = recommendLanguage("game-engine");
console.log("اللغة الموصى بها: " + chosen);
